// Input: The clean JSON from API Ninjas
const allStocks = $input.all();

// 1. Filter for Technology Sector
// API Ninjas uses "Information Technology"
const techStocks = allStocks.filter(stock => 
  stock.json.sector === "Information Technology"
);

// 2. Limit to Top 10-25 to save Finnhub credits
// (Optional: Shuffle them if you want a random sample each day)
const candidates = techStocks.slice(0, 100);

return candidates.map(stock => ({
  json: {
    symbol: stock.json.ticker,  // Remap 'ticker' to 'symbol' for Finnhub
    name: stock.json.company_name,
    sector: stock.json.sector
  }
}));

// Get the metric object from Finnhub
const metric = $json.metric;
const symbol = $json.symbol;

// Initialize Score
let score = 0;
let reasons = [];

// --- PILLAR 1: VALUE (Max 40 pts) ---
// P/E Ratio: We want "Reasonable", not just "Low".
// < 15 is great value (+20), 15-30 is fair for Tech (+10), > 50 is expensive (-10)
const pe = metric.peTTM || 0;
const eps = metric.epsTTM || 0;

if (pe > 0 && pe < 15) { score += 20; reasons.push("Great Value"); }
else if (pe >= 15 && pe < 30) { score += 10; reasons.push("Fair Value"); }
else if (pe > 60) { score -= 10; reasons.push("Overvalued"); }

// Price to Sales (Good for checking if a non-profitable tech stock is hyped)
// < 3 is cheap, > 10 is very expensive
const ps = metric.psTTM || 0;
if (ps < 3) score += 10; 
else if (ps > 10) score -= 5;

// --- PILLAR 2: QUALITY (Max 30 pts) ---
// ROE (Return on Equity): Critical for Tech. > 15% is the target.
const roe = metric.roeTTM || 0;
if (roe > 20) { score += 20; reasons.push("High Efficiency (ROE > 20%)"); }
else if (roe > 10) { score += 10; }

// Debt to Equity: Avoid debt-heavy companies (> 100% or 1.0)
// Note: Finnhub sometimes returns this as 'longTermDebt/equity' or similar
const debtEq = metric['totalDebt/totalEquityAnnual'] || 0;
if (debtEq < 0.5) score += 10; // Very safe
else if (debtEq > 1.5) score -= 10; // Risky leverage

// --- PILLAR 3: GROWTH (Max 30 pts) ---
// EPS Growth (Year over Year)
const epsGrowth = metric.epsGrowthTTMYoy || 0;
if (epsGrowth > 20) { score += 20; reasons.push("High Growth (>20%)"); }
else if (epsGrowth > 5) { score += 10; reasons.push("Moderate Growth"); }
else if (epsGrowth < 0) { score -= 20; reasons.push("Shrinking Earnings"); }

// --- THE VERDICT ---
// You can adjust this threshold. 50 is a "Solid Buy".
const isBuy = score >= 50;

return {
  json: {
    symbol: symbol,
    fundamental_score: score,
    pass_filter: isBuy,
    key_metrics: {
      PE: pe.toFixed(2),
      EPS: eps.toFixed(2),
      ROE: roe.toFixed(2),
      Growth: epsGrowth.toFixed(2) + "%"
    },
    analysis: reasons.join(", ")
  }
};

var fundData = $('Merge Metrics and Quote').item.json;

const ta = $json;
const rsi = parseFloat(ta.rsi_data?.values?.[0]?.rsi || '50');
const macd = parseFloat(ta.macd_data?.values?.[0]?.macd || '0');
const macdSignal = parseFloat(ta.macd_data?.values?.[0]?.macd_signal || '0');
const ema200 = parseFloat(ta.ema_data?.values?.[0]?.ema || '0');
const symbol = ta.rsi_data?.meta?.symbol;
const currentPrice = fundData.c;
const fundScore = fundData.fundamental_score || 0;

  // --- 4. SCORING LOGIC ---
  let techScore = 0;
  let signals = [];

  // A. MOMENTUM (RSI)
  if (rsi < 30) {
      techScore += 30;
      signals.push("Oversold (RSI < 30)");
  } else if (rsi < 45 && rsi > 30) {
      techScore += 10; // Dip in uptrend
  } else if (rsi > 70) {
      techScore -= 10; // Overbought risk
  }

  // B. TREND (MACD)
  const histogram = macd - macdSignal;
  if (histogram > 0) {
      techScore += 20;
      if (histogram < 0.5) signals.push("MACD Bullish Cross");
  }

  // C. DIRECTION (EMA 200)
  // Only check this if we successfully retrieved a price > 0
  if (currentPrice > 0) {
      if (currentPrice > ema200) {
          techScore += 20;
          signals.push("Uptrend (Above EMA200)");
      } else {
          techScore -= 15; // Trading below 200 EMA is risky
      }
  }

  // --- 5. FINAL OUTPUT ---
  return {
    json: {
      symbol: symbol,
      total_score: fundScore + techScore, // Grand Total
      fundamental_score: fundScore,
      technical_score: techScore,
      signals: signals.join(", "),
      details: {
          price: currentPrice,
          rsi: rsi.toFixed(2),
          macd: macd.toFixed(4),
          ema_200: ema200.toFixed(2),
          pe: fundData.key_metrics?.PE || "N/A"
      }
    }
  };

const taScoreModel = $('Calculate TA Score');
const targetSymbol = taScoreModel.item.json.symbol;

let newsCount = 0;
let totalNewsScore = 0;

for (const article of $json.feed) {
    // Find the score specifically for OUR ticker (articles often mention multiple)
    const sentimentObj = article.ticker_sentiment.find(t => t.ticker === targetSymbol);
    if (sentimentObj) {
        totalNewsScore += parseFloat(sentimentObj.ticker_sentiment_score);
        newsCount++;
    }
}

const avgNewsScore = newsCount > 0 ? (totalNewsScore / newsCount) : 0;
let avgNewsScoreDefinition = '';

if (avgNewsScore <= -0.35) {
  avgNewsScoreDefinition = 'Bearish';
} else if (avgNewsScore <= -0.15 && avgNewsScore > -0.35) {
  avgNewsScoreDefinition = 'Somewhat Bearish';
} else if (avgNewsScore < 0.15 && avgNewsScore > -0.15) {
  avgNewsScoreDefinition = 'Neutral';
} else if (avgNewsScore < 0.35 && avgNewsScore >= 0.15) {
  avgNewsScoreDefinition = 'Somewhat Bullish';
} else if (avgNewsScore >= 0.35) {
  avgNewsScoreDefinition = 'Bullish';
}

return {
  json: {
    symbol: targetSymbol,
    fund_and_ta_score: taScoreModel.item.json,
    news_sentiment: avgNewsScore.toFixed(3),
    news_sentiment_definition: avgNewsScoreDefinition
  }
}

// 1. Get all articles returned by the RSS node
const symbol = $("Calculate TA Score").first().json.symbol;


// 2. Build a single "Master String" for the AI
// We include Title + Content Snippet + Date
let fullContext = `Recent News for ${symbol}:\n\n`;

$("RSS Read: Yahoo Finance News").all().forEach((item, index) => {
    const title = item.json.title || "No Title";
    // Yahoo often puts the good stuff in 'contentSnippet' or 'content'
    const desc = item.json.contentSnippet || item.json.content || "";
    const date = item.json.pubDate || "";

    fullContext += `${index + 1}. TITLE: ${title}\n`;
    fullContext += `   SUMMARY: ${desc}\n`;
    fullContext += `   DATE: ${date}\n`;
    fullContext += `   ---\n`;
});

// 3. Return ONE item (so OpenAI runs only once)
return {
    json: {
        symbol: symbol,
        news_context: fullContext
    }
};

// 1. Get the raw text output from the LLM
// Note: Check your previous node's output name. It might be 'text', 'message.content', or 'output'.
// Based on your snippet, it looks like 'text'.
const rawContent = $json.text || "";

console.log($('Calculate TA Score').item.json.symbol);

// 2. Clean up the string
// Remove markdown wrappers like ```json and ``` that LLMs love to add
let cleanJson = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

// 3. Parse it into a real object
try {
    // This turns the string "{\n \"sentiment_score\": ...}" into a real object
    const parsedData = JSON.parse(cleanJson);

    // 4. Return the clean data to the flow
    return {
        json: {
            // Keep the symbol for the next step
            symbol: $json.symbol,
            yahoo_finance_news_sentiment: { ...parsedData, sentiment_score_description: '-1 = Bearish; 1 = Bullish, 0 = Neutral' },
            fundamentals_and_TA_scope: $json.fund_and_ta_score,
            alpha_vantage_news: {
              news_sentiment: $json.news_sentiment,
              news_sentiment_definition: $json.news_sentiment_definition
            },
            twitterInsights: $json.twitterInsights,
            analystsInsights: {
             analystsEstimates: $json.analystEstimates,
             consensus: $json.gradeConsensus,
             priceTargetConsensus: $json.priceTargetConsensus
            }
            // Spread the parsed fields (sentiment_score, primary_driver, risk_flag)

        }
    };
} catch (error) {
    // If the LLM messed up the syntax, return a safe default so the workflow doesn't crash
    return {
        json: {
            symbol: $json.symbol,
            sentiment_score: 0,
            primary_driver: "Error Parsing AI Response",
            risk_flag: "Manual Check Required",
            error: error.message,
            raw_output: rawContent // Keep this to debug later
        }
    };
}

