// 1. Find the message part of the response
const symbol = $("Calculate TA Score").first().json.symbol;

const outputs = $json.output || [];
const messageItem = outputs.find(item => item.type === 'message');

// 2. Extract the text string
const rawText = messageItem.content[0].text;

// 3. Clean up (just in case it adds markdown) and Parse
const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

try {
    const parsedData = JSON.parse(cleanText);

    return {
        json: {
          twitterInsights: {
            symbol: symbol, // You might want to pass this from previous node
            x_sentiment_score: parsedData.sentiment_score,
            x_summary: parsedData.summary,
            x_citations: outputs.find(o => o.type === 'message')?.content[0]?.annotations?.map(x => x.url) || null,
            x_citations_count: outputs.find(o => o.type === 'message')?.content[0]?.annotations?.length || 0

          }
        }
    };
} catch (error) {
    return {
        json: {
          twitterInsights: {
            error: "Failed to parse Grok JSON",
            raw_output: rawText
          }
        }
    };
}

if ($input.first().json.error) {
  return {
    json: { analystEstimates: "paid subscription is required for this asset" },
  };
}

// Input: The array of estimates from FMP
// Note: FMP usually returns them sorted by date. We need to find "Next Year".
const estimates = $input.all();
const currentYear = new Date().getFullYear();

// 1. Find the forecast for Next Year (e.g., 2026) and the Year After
const nextYearEst = estimates.find(
  (e) => new Date(e.json.date).getFullYear() === currentYear + 1,
);
const currentYearEst = estimates.find(
  (e) => new Date(e.json.date).getFullYear() === currentYear,
);

let growthScore = 0;
let forwardPE = 0;
let growthRate = 0;

if (nextYearEst && currentYearEst) {
  // A. Calculate Revenue Growth %
  const revenueGrowth =
    ((nextYearEst.json.revenueAvg - currentYearEst.json.revenueAvg) /
      currentYearEst.json.revenueAvg) *
    100;
  growthRate = revenueGrowth;

  // B. Score the Growth
  if (revenueGrowth > 20)
    growthScore += 30; // Hyper Growth
  else if (revenueGrowth > 10)
    growthScore += 20; // Solid Growth
  else if (revenueGrowth > 0)
    growthScore += 5; // Slow Growth
  else growthScore -= 20; // Shrinking (Red Flag!)

  // C. Calculate Forward P/E (Valuation)
  // Assume we have 'currentPrice' from previous TwelveData node
  const currentPrice = $("Calculate TA Score").first().json.details.price;

  if (nextYearEst.json.epsAvg > 0) {
    forwardPE = currentPrice / nextYearEst.json.epsAvg;

    // Bonus: If Forward P/E is lower than Trailing P/E, the stock is getting "cheaper"
    if (forwardPE < 30) growthScore += 10;
  }
}

// 3. Return the new data
return {
  json: {
    analystEstimates: {
      symbol: $input.first().json.symbol,
      forward_growth_projected: growthRate.toFixed(2) + "%",
      forward_pe: forwardPE.toFixed(2),
      growth_score: growthScore,
    }
  }
};

// return {
//         json: {
//           analystEstimates: $input.all()
//         }
//     };

return {
        json: {
          gradeConsensus: $input.first().json.error ? 'paid subscription is required for this asset' : $input.all()
        }
    };

return {
        json: {
          priceTargetConsensus: $input.first().json.error ? 'paid subscription is required for this asset' : $input.all()
        }
    };

const stocks = [$json];

let htmlOutput = "";

for (const item of stocks) {
  const data = item;

  // --- 1. DATA MAPPING ---
  const sym = data.symbol;
  const yahoo = data.yahoo_finance_news_sentiment || {};
  const ta = data.fundamentals_and_TA_scope || {};
  const av = data.alpha_vantage_news || {};
  const twitter = data.twitterInsights || {};
  const analysts = data.analystsInsights || {};

  // Nested Analyst Data
  const est = analysts.analystsEstimates || {};
  // Handle n8n's nested structure for consensus/targets (sometimes it wraps in .json)
  const consRaw =
    analysts.consensus && analysts.consensus[0]
      ? analysts.consensus[0].json || analysts.consensus[0]
      : {};
  const targetRaw =
    analysts.priceTargetConsensus && analysts.priceTargetConsensus[0]
      ? analysts.priceTargetConsensus[0].json ||
        analysts.priceTargetConsensus[0]
      : {};

  // --- 2. FORMATTING HELPERS ---
  // Color circles based on score
  const getMood = (score) => {
    const s = parseFloat(score);
    if (s > 0.2) return "🟢";
    if (s < -0.2) return "🔴";
    return "⚪";
  };

  // Top 5 Twitter Links
  let twitterLinks = "";
  if (twitter.x_citations && Array.isArray(twitter.x_citations)) {
    twitterLinks = twitter.x_citations
      .slice(0, 5)
      .map((link, i) => {
        return `<a href="${link}">[${i + 1}]</a>`;
      })
      .join(" ");
  }

  // --- 3. BUILD HTML STRING ---
  htmlOutput += `<b>📊 Researched Ticker: ${sym}</b> (Score: ${ta.total_score || "N/A"}/100)\n`;

  // A. Fundamentals & TA (Compact Line)
  htmlOutput += `💰 <b>Price:</b> $${ta.details?.price} | <b>P/E:</b> ${ta.details?.pe} | <b>RSI:</b> ${ta.details?.rsi}\n`;
  htmlOutput += `📈 <b>Tech Signal:</b> ${ta.signals || "N/A"} (Score: ${ta.technical_score})\n`;

  // B. Yahoo News (AI Context)
  htmlOutput += `${getMood(yahoo.sentiment_score)} <b>News (${yahoo.sentiment_score}):</b> ${yahoo.primary_driver || "N/A"}\n`;
  if (yahoo.risk_flag && !yahoo.risk_flag.includes("None")) {
    htmlOutput += `⚠️ <i>Risk: ${yahoo.risk_flag}</i>\n`;
  }

  // C. Alpha Vantage & Twitter (Social)
  htmlOutput += `🗞 <b>AlphaVantage:</b> ${av.news_sentiment} (${av.news_sentiment_definition})\n`;
  htmlOutput += `${getMood(twitter.x_sentiment_score)} <b>X (Twitter):</b> Score ${twitter.x_sentiment_score} (${twitter.x_citations_count} citations)\n`;
  htmlOutput += `<i>"${twitter.x_summary || "No summary"}"</i>\n`;
  if (twitterLinks) htmlOutput += `🔗 Sources: ${twitterLinks}\n`;

  // D. Analysts (Wall St. View)
  if (consRaw.consensus) {
    htmlOutput += `👨‍💼 <b>Analysts:</b> Consensus <b>${consRaw.consensus || "N/A"}</b> (B:${consRaw.buy || 0} H:${consRaw.hold || 0} S:${consRaw.sell || 0})\n`;
    htmlOutput += `🎯 <b>Targets:</b> Low $${targetRaw.targetLow} | Avg $${targetRaw.targetConsensus} | High $${targetRaw.targetHigh}\n`;
    htmlOutput += `🚀 <b>Growth '26:</b> ${est.forward_growth_projected} (Fwd P/E: ${est.forward_pe})\n\n`;
  }

  htmlOutput += `--------------------------------\n\n`;
}

// Output specifically for the Telegram Node
return {
  json: {
    html_message: htmlOutput,
  },
};
